sql:
SELECT COUNT(*) AS active_customers_emaa
FROM `workspace`.`sales`.`customer_segments`
WHERE `is_active` = TRUE AND `region` = 'EMEA' AND `region` IS NOT NULL AND `is_active` IS NOT NULL;

SELECT COUNT(*) AS active_customers_na
FROM `workspace`.`sales`.`customer_segments`
WHERE `region` = 'North America' AND `is_active` = true AND `region` IS NOT NULL AND `is_active` IS NOT NULL;

SELECT COUNT(DISTINCT `customer_id`) AS churned_customers_emaa
FROM `workspace`.`sales`.`customer_segments`
WHERE `region` = 'EMEA' AND `is_churned` = true;

SELECT COUNT(*) AS active_enterprise_accounts
FROM `workspace`.`sales`.`customer_segments`
WHERE `is_enterprise` = TRUE AND `is_active` = TRUE;

SELECT COUNT(*) AS num_customers
FROM `workspace`.`sales`.`customer_segments`
WHERE `is_active` = FALSE AND `is_churned` = FALSE AND `is_active` IS NOT NULL AND `is_churned` IS NOT NULL;
